<template><div class="page"><div class="page-header"><div><el-button link @click="router.back()"><ArrowLeft/>返回题库</el-button><h1 class="page-title">Excel导入题目</h1><p class="page-description">Excel中的课程名称必须与系统已有课程完全一致。</p></div><el-button @click="downloadTemplate"><Download/>下载模板</el-button></div><div class="card card-body" style="max-width:800px"><el-alert title="必填列：题型、题干、正确答案、难度、分值、课程。选择题至少填写A-D四个选项。" type="info" show-icon :closable="false"/><el-upload drag :auto-upload="false" accept=".xlsx" :limit="1" :on-change="x=>file=x.raw" :on-remove="()=>file=null" style="margin-top:20px"><el-icon class="el-icon--upload"><UploadFilled/></el-icon><div class="el-upload__text">拖拽Excel文件，或<em>点击选择</em></div></el-upload><el-button type="primary" :loading="loading" style="margin-top:18px" @click="submit">开始导入</el-button><div v-if="result" class="import-result"><el-result :icon="result.failed?'warning':'success'" title="导入完成" :sub-title="`总计 ${result.total}，成功 ${result.success}，重复 ${result.duplicate}，失败 ${result.failed}`"/><el-table v-if="result.errors?.length" :data="result.errors" max-height="260"><el-table-column prop="row" label="行号" width="80"/><el-table-column prop="reason" label="失败原因"/></el-table></div></div></div></template>
<script setup>import{ref}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import{questionsApi}from'../../api';const router=useRouter(),file=ref(null),loading=ref(false),result=ref(null);const submit=async()=>{if(!file.value)return ElMessage.warning('请选择Excel文件');const data=new FormData();data.append('file',file.value);loading.value=true;try{result.value=await questionsApi.import(data)}finally{loading.value=false}};const downloadTemplate=()=>{location.href=`${questionsApi.exportUrl}?template=1`}</script>
<style scoped>.import-result{margin-top:18px}</style>
